package de.lazytv.pro.player;
import android.content.Context;import android.content.SharedPreferences;
public final class PlaybackResumeStore {private static final String PREFS="lazytv_resume";public static final long MIN_RESUME_MS=10_000L;private static final long COMPLETE_WINDOW_MS=90_000L;private final SharedPreferences prefs;public static final class Entry{public final long position,duration,timestamp;Entry(long position,long duration,long timestamp){this.position=position;this.duration=duration;this.timestamp=timestamp;}}public PlaybackResumeStore(Context context){prefs=context.getSharedPreferences(PREFS,Context.MODE_PRIVATE);}private String key(String id,String field){return id+"_"+field;}public Entry get(String id){if(id==null||id.isEmpty()||!prefs.contains(key(id,"p")))return null;long position=prefs.getLong(key(id,"p"),0),duration=prefs.getLong(key(id,"d"),0);if(position<MIN_RESUME_MS||(duration>0&&duration-position<=COMPLETE_WINDOW_MS)){clear(id);return null;}return new Entry(position,duration,prefs.getLong(key(id,"t"),0));}public void save(String id,long position,long duration){if(id==null||id.isEmpty()||position<MIN_RESUME_MS)return;if(duration>0&&duration-position<=COMPLETE_WINDOW_MS){clear(id);return;}prefs.edit().putLong(key(id,"p"),position).putLong(key(id,"d"),duration).putLong(key(id,"t"),System.currentTimeMillis()).apply();}public void clear(String id){if(id==null||id.isEmpty())return;prefs.edit().remove(key(id,"p")).remove(key(id,"d")).remove(key(id,"t")).apply();}}
